head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > getDisplayValue]<br/>컴포넌트에 표시되고 있는 입력값을 반환합니다.",
    "validation" : [                
        "displayFormatFunc 속성으로 입력값이 표시되는 포맷을 설정할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        displayFormatFunc : "scwin.fn_displayFormatFunc",   
        delimiter : "/",
        style : 'width:300px',
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createLabel('label="displayFormatFunc 에 의해 yyyy-MM-dd 포맷 적용상태"', '', 'label1');
    $c.gcm.createEmptyInputCalendar(cList);
}



scwin.btn_getDisplayValue_onclick = function (e) {
    let rtn = ''

    rtn = target1.getDisplayValue();
    wf_body_bottom.getObj("scwin").setReturnValue('getDisplayValue : ' + rtn);  
}



scwin.btn_setValue_onclick = function (e) {
    target1.setValue("20251111130519");
};



// 사용자 정의 함수
scwin.fn_displayFormatFunc = function(valueType) {   
    let dp_format = "yyyy-MM-dd";

    return dp_format;
}
